using System.Text.Json.Serialization;

namespace PixousDocIntelligence.Domain.Planning;

/// <summary>
/// A versioned, immutable plan generated by Gemini from natural language instructions.
/// Every batch in a document extraction job executes against this frozen plan.
/// </summary>
public class ExtractionPlan
{
    [JsonPropertyName("plan_id")]
    public string PlanId { get; set; } = $"PLAN-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}";

    [JsonPropertyName("schema_version")]
    public int SchemaVersion { get; set; } = 1;

    [JsonPropertyName("created_at")]
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    [JsonPropertyName("user_instruction")]
    public string UserInstruction { get; set; } = string.Empty;

    [JsonPropertyName("extraction_mode")]
    public string ExtractionMode { get; set; } = "requested_fields"; // "requested_fields", "full_content", "section_focused"

    [JsonPropertyName("target_document_type")]
    public string TargetDocumentType { get; set; } = "Generic Document";

    [JsonPropertyName("desired_fields")]
    public List<DynamicFieldDefinition> DesiredFields { get; set; } = new();

    [JsonPropertyName("preserve_tables")]
    public bool PreserveTables { get; set; } = true;

    [JsonPropertyName("preserve_cross_page_tables")]
    public bool PreserveCrossPageTables { get; set; } = true;

    [JsonPropertyName("normalization_rules")]
    public NormalizationRules NormalizationRules { get; set; } = new();

    [JsonPropertyName("output_instructions")]
    public string OutputInstructions { get; set; } = string.Empty;
}

/// <summary>
/// Definition of a dynamically planned field to extract.
/// </summary>
public class DynamicFieldDefinition
{
    [JsonPropertyName("field_key")]
    public string FieldKey { get; set; } = string.Empty;

    [JsonPropertyName("field_label")]
    public string FieldLabel { get; set; } = string.Empty;

    [JsonPropertyName("value_type")]
    public string ValueType { get; set; } = "string"; // "string", "number", "date", "currency", "boolean", "array"

    [JsonPropertyName("description")]
    public string Description { get; set; } = string.Empty;

    [JsonPropertyName("aliases")]
    public List<string> Aliases { get; set; } = new();

    [JsonPropertyName("is_mandatory")]
    public bool IsMandatory { get; set; }

    [JsonPropertyName("unit_or_format")]
    public string? UnitOrFormat { get; set; }
}

public class NormalizationRules
{
    [JsonPropertyName("date_format")]
    public string DateFormat { get; set; } = "YYYY-MM-DD";

    [JsonPropertyName("currency_standard")]
    public string CurrencyStandard { get; set; } = "ISO-4217 (e.g. USD, INR, EUR)";

    [JsonPropertyName("unit_conversion")]
    public string? UnitConversion { get; set; }

    [JsonPropertyName("deduplication_strategy")]
    public string DeduplicationStrategy { get; set; } = "evidence_and_page_aware";
}
